contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that will be fuzzed by inputs
    function run(address[] calldata tos, uint[] calldata vals) public payable {
        require(true);

        // observe before-values
        address before_from = c.from();
        address before_caddress = c.caddress();

        // attempt the call and record whether it reverted
        bool reverted;
        try c.transfer(tos, vals) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general invariant: if the call did not revert then it must have returned true
        // and the contract's public stored addresses remain unchanged.
        assert(reverted || (c.from() == before_from && c.caddress() == before_caddress));
    }

    receive() external payable {}
}

