contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry with inputs that drive C.transfer
    function run(address[] memory _tos, uint[] memory v, address caller) public payable {
        // precondition: ensure arrays have same length to avoid out-of-bounds inside test call
        require(_tos.length == v.length);
        // capture observable state before the call
        address before_from = c.from();
        address before_caddress = c.caddress();

        // perform the call and record whether it reverted
        bool reverted;
        bool ret;
        // We must call c.transfer from this contract; the contract C requires msg.sender == from.
        // To model both possibilities, we simulate calling only (we cannot change msg.sender), so
        // the general rule will relate success to the stored from value.
        try c.transfer(_tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // After the call, observable public variables should be unchanged regardless of success
        address after_from = c.from();
        address after_caddress = c.caddress();

        // General rule asserted: if the call did not revert then it must have returned true,
        // the public addresses did not change, and it can only succeed when msg.sender equals before_from
        // (here msg.sender is this contract, so success implies before_from == address(this)).
        assert((!reverted) == (ret == true)
               && after_from == before_from
               && after_caddress == before_caddress
               && (!reverted ? (before_from == address(this) && _tos.length > 0) : true)
        );
    }

    receive() external payable {}
}

