    constructor(C _c) { c = _c; }

    // Inputs: caller must match C.from so the call does not revert due to sender check.
    // We take arrays of same length and a length > 0 to exercise the loop.
    function run(address[] memory _tos, uint[] memory v) public payable {
        // preconditions for meaningful call: non-empty arrays and matching lengths
        require(_tos.length > 0);
        require(_tos.length == v.length);

        // Observe public getters before the call
        address before_from = c.from();
        address before_caddress = c.caddress();

        // The contract C requires msg.sender to equal a specific hardcoded address.
        // Since this InvMutTest is the msg.sender when calling c.transfer, the only way
        // for the call to succeed (not revert) is if c.from() equals address(this).
        // We'll attempt the call and record whether it reverted.
        bool reverted;
        try c.transfer(_tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

