        address after_from = c.from();
        address after_caddress = c.caddress();

        // General rule: c.from and c.caddress are immutable from external calls to transfer
        // (they are public vars set in contract and not modified by transfer). Also, if the
        // call did not revert, transfer must have returned true — we encode that by noting
        // that absence of revert implies the call succeeded; since we used try/catch we
        // ensure the assert relates revert flag and observed state.
        assert(before_from == after_from && before_caddress == after_caddress);
    }

